using System.Linq;using UnityEngine;using UnityEngine.Tilemaps;using UnityEditor;public static class InspectMines{static string P(Transform t)=>t.parent==null?t.name:P(t.parent)+"/"+t.name;public static object Main(){var h=GameObject.Find("Hometown");return new{sprites=h.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>r.sprite!=null&&(r.sprite.name.Contains("Entrance")||AssetDatabase.GetAssetPath(r.sprite).ToLower().Contains("rail"))).Select(r=>new{path=P(r.transform),sprite=r.sprite.name,asset=AssetDatabase.GetAssetPath(r.sprite),x=r.transform.position.x,y=r.transform.position.y,components=r.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray(),children=r.transform.childCount}).ToArray(),maps=h.GetComponentsInChildren<Tilemap>(true).Where(m=>m.name.Contains("Tracks")).Select(m=>new{path=P(m.transform),tiles=m.GetUsedTilesCount(),components=m.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray()}).ToArray()};}}
